command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9b468483d7dc259564a142396d7ee29f123ede73"
$candidate="dfc8703394e8c750beaaaa7ee9cea9d81ddeba2c"
Set-Location -LiteralPath $repo
& git fetch origin main work/shell-provider-copyin-20261008 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main changed"}
if((& git rev-parse refs/remotes/origin/work/shell-provider-copyin-20261008).Trim() -ne $candidate){throw "candidate differs"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "canonical checkout dirty"}
try {
 & git switch --detach $candidate
 if($LASTEXITCODE -ne 0){throw "checkout failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "Copy-in Release build failed"}
 & python -X utf8 tests\winui\test_shell_provider_copyin_contract.py
 if($LASTEXITCODE -ne 0){throw "Copy-in native source contract failed"}
 & python -X utf8 tests\winui\test_shell_provider_copyin_gui.py --configuration Release
 if($LASTEXITCODE -ne 0){throw "Copy-in focused GUI failed"}
 Write-Host "SHELL_PROVIDER_COPYIN_VALIDATION=PASS"
} finally {
 & git switch main
 if($LASTEXITCODE -ne 0){throw "restore main failed"}
 & git merge --ff-only origin/main
 if($LASTEXITCODE -ne 0){throw "restore main ff failed"}
}
